import{_ as t,c as o,o as r,ae as a}from"./chunks/framework.CliRSA9F.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"more/faq.md","filePath":"more/faq.md"}'),s={name:"more/faq.md"};function n(i,e,l,d,h,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h3 id="what-are-the-pricing-plans-for-podseo" tabindex="-1">What are the pricing plans for PodSEO? <a class="header-anchor" href="#what-are-the-pricing-plans-for-podseo" aria-label="Permalink to &quot;What are the pricing plans for PodSEO?&quot;">​</a></h3><p>PodSEO offers multiple plans to fit different needs — from independent podcasters to agencies managing multiple shows. Each plan includes different features, such as keyword tracking limits, access to visibility insights, and competitor discovery tools.</p><p>You can find the full breakdown of our pricing and features on our <a href="https://podseo.com/pricing/" target="_blank" rel="noreferrer">Pricing Page</a>.</p><br><h3 id="is-there-a-free-version-of-podseo" tabindex="-1">Is there a free version of PodSEO? <a class="header-anchor" href="#is-there-a-free-version-of-podseo" aria-label="Permalink to &quot;Is there a free version of PodSEO?&quot;">​</a></h3><p>Yes! PodSEO offers a free version with specific limitations — perfect if you&#39;re just getting started. Here&#39;s what you get:</p><p><strong>Free Plan Includes:</strong></p><ul><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong>: Up to 5 tracked keywords in total, of which a maximum of 3 can be Primary</li><li><strong><a href="/features/show-visibility.html">Show Visibility</a></strong>: In Organic Visibility, you see every keyword row with its rankings and search volume; your 3 best-ranked keywords are shown in clear and the others are masked (upgrade to see them all)</li><li><strong><a href="/features/planner.html">Planner</a></strong>: Title and Author metadata alignment (Cover Art, Description, and Episode analysis require upgrade), with up to 3 active planned episodes</li><li><strong><a href="/features/competitive-analysis.html">Competitors</a></strong>: Track up to 2 competitors</li><li><strong>Credits</strong>: 10 monthly credits for actions such as episode analysis and clip creation</li><li><strong><a href="/features/lucia-ai-assistant.html">LUCIA AI Chat</a></strong>: 5 messages per month</li><li><strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong>: Full access to tracking charts and historical data</li><li><strong>Basic Platform Data</strong>: Rankings across Apple Podcasts, Spotify, Amazon Music, and YouTube Music</li></ul><p><strong>Paid Plan Benefits:</strong></p><ul><li><strong>Full Visibility</strong>: Unlock all keyword rankings in <a href="/features/show-visibility.html">Show Visibility</a></li><li><strong>A much larger keyword allowance</strong>: Podcaster 100, Producer 500, Agency 50,000 tracked keywords in total (the 3-Primary cap stays the same on every plan)</li><li><strong>Complete Metadata Analysis</strong>: Full AI-powered recommendations for Cover Art, Description, and Episodes in the Planner</li><li><strong>Advanced Features</strong>: Enhanced <a href="/features/competitor-finder.html">competitor discovery</a> and premium analytics</li></ul><p>When you&#39;re ready to unlock the full platform, you can upgrade at any time. Learn more on our <a href="https://podseo.com/pricing/" target="_blank" rel="noreferrer">Pricing Page</a>.</p><br><h3 id="what-s-the-difference-between-primary-secondary-and-monitored-keywords" tabindex="-1">What&#39;s the difference between Primary, Secondary, and Monitored keywords? <a class="header-anchor" href="#what-s-the-difference-between-primary-secondary-and-monitored-keywords" aria-label="Permalink to &quot;What&#39;s the difference between Primary, Secondary, and Monitored keywords?&quot;">​</a></h3><p><strong>Primary Keywords</strong> (maximum 3 per podcast on every plan):</p><ul><li>Your most important target keywords for optimization</li><li>Generate the deepest analysis and recommendations</li><li>Should represent your core podcast topics</li></ul><p><strong>Secondary Keywords</strong>:</p><ul><li>Support your primary keyword strategy</li><li>No separate tier cap — they count toward your account&#39;s total keyword allowance</li><li>Provide broader topic coverage and discovery opportunities</li></ul><p><strong>Monitored Keywords</strong>:</p><ul><li>Keywords you want to monitor but not actively optimize for</li><li>No separate tier cap — they count toward your account&#39;s total keyword allowance</li><li>Perfect for competitive intelligence and market monitoring</li></ul><p><strong>How the allowance works:</strong> each plan has one total keyword allowance shared across every podcast in your account (Free 5, Podcaster 100, Producer 500, Agency 50,000, Enterprise 500,000). Primary, Secondary, and Monitored keywords all draw from that pool; the only per-tier rule is the three-Primary cap per podcast. Adding a second podcast does not add a second allowance.</p><p>Learn more about building your keyword strategy in our <a href="/features/keyword-strategy.html">Keyword Strategy guide</a> or follow our step-by-step <a href="/getting-started/workflow.html">PodSEO Workflow</a>.</p><br><h3 id="how-often-should-i-check-my-metadata-alignment" tabindex="-1">How often should I check my metadata alignment? <a class="header-anchor" href="#how-often-should-i-check-my-metadata-alignment" aria-label="Permalink to &quot;How often should I check my metadata alignment?&quot;">​</a></h3><p>We recommend reviewing your metadata alignment in the <a href="/features/planner.html">Planner</a>:</p><ul><li><strong>Initially</strong>: After adding your podcast and setting up your keyword strategy</li><li><strong>After Changes</strong>: Whenever you update your cover art, description, or add new episodes</li><li><strong>Monthly</strong>: As a regular optimization check to discover new opportunities</li><li><strong>Before Big Launches</strong>: Prior to major episode releases or series launches</li></ul><p>Click &quot;Get AI suggestions to improve&quot; in the Planner&#39;s Metadata/Keyword Alignment card for personalized recommendations based on your current keyword strategy.</p><br><h3 id="why-do-i-see-different-rankings-on-different-platforms" tabindex="-1">Why do I see different rankings on different platforms? <a class="header-anchor" href="#why-do-i-see-different-rankings-on-different-platforms" aria-label="Permalink to &quot;Why do I see different rankings on different platforms?&quot;">​</a></h3><p>Each podcasting platform runs its own search, and none of them publishes its full ranking formula. What they do say:</p><p><strong>Apple Podcasts</strong>: Search is ordered by metadata (show name, channel name, episode titles), popularity (followers and plays), and engagement from search results. Ratings and reviews aren&#39;t a direct search input, but they reflect the listening and follows that are. In PodSEO&#39;s observations the Author field also appears to matter more than most creators expect on Apple. <strong>Spotify</strong>: Recommends searchable titles and descriptions (first 250 characters), transcripts, chapters, and topic/guest tags; click-through from search influences relevance. <strong>Amazon Music</strong> and <strong>YouTube Music</strong>: Neither publishes search guidance for podcasts; YouTube Music behaves like a video platform with its own search and recommendations.</p><p>This is why PodSEO tracks all major platforms — what works on one platform may need adjustment for others. Use <a href="/features/show-visibility.html">Show Visibility</a> to see your performance across all platforms, <a href="/features/competitive-analysis.html">Competitive Analysis</a> to see how competitors rank, and the <a href="/academy/platform-algorithm-deep-dive-how-spotify-vs-apple-podcasts-really-rank-shows.html">platform algorithm guide</a> for what&#39;s documented versus assumed.</p><br><h3 id="why-are-my-rankings-different-from-what-i-see-in-my-own-podcast-app" tabindex="-1">Why are my rankings different from what I see in my own podcast app? <a class="header-anchor" href="#why-are-my-rankings-different-from-what-i-see-in-my-own-podcast-app" aria-label="Permalink to &quot;Why are my rankings different from what I see in my own podcast app?&quot;">​</a></h3><p>PodSEO collects rankings as a neutral listener in the <strong>United States</strong> sees them. Your own app shows results for your device&#39;s country, language, and sometimes your listening history, so small differences are normal. If your audience is mainly outside the US, paid plans let you add search countries per podcast in <strong>Settings → Podcasts</strong> and switch between them in <a href="/features/keyword-tracker.html#search-countries">Keyword Tracker</a> (Podcaster 1 additional country, Producer 5, Agency 10, Enterprise unlimited). Search countries are separate from chart countries and review storefronts.</p><br><h3 id="what-does-keyword-search-volume-mean" tabindex="-1">What does keyword search volume mean? <a class="header-anchor" href="#what-does-keyword-search-volume-mean" aria-label="Permalink to &quot;What does keyword search volume mean?&quot;">​</a></h3><p>Search volume tells you roughly how many times a month people search for a keyword. PodSEO shows it as one of six levels, drawn as a 6-step green meter, each with a round monthly range:</p><table tabindex="0"><thead><tr><th>Level</th><th>Searches per month</th></tr></thead><tbody><tr><td>Very niche</td><td>Under 100</td></tr><tr><td>Niche</td><td>100–250</td></tr><tr><td>Small</td><td>250–1K</td></tr><tr><td>Medium</td><td>1K–2.5K</td></tr><tr><td>Popular</td><td>2.5K–10K</td></tr><tr><td>Very popular</td><td>10K+</td></tr></tbody></table><p>In narrow table columns you see the meter only: hover over it (or focus it with the keyboard) to read the level and range, for example &quot;Small · 250–1K searches/mo&quot;. Wider spots, such as the keyword search dropdown in Keyword Strategy and the Keyword Tracker cards on mobile, show the range next to the meter. A clock icon means the keyword hasn&#39;t been measured yet; its level fills in after the next periodic check.</p><p>Volume isn&#39;t good or bad on its own. A popular keyword brings more searches but usually more shows competing for them, while a niche keyword brings fewer searches that are often easier to win and come from listeners who know exactly what they want. Use volume together with Difficulty and Popularity (how crowded the keyword is) to pick the right mix for your show.</p><br><h3 id="how-long-does-it-take-to-see-results-from-optimization" tabindex="-1">How long does it take to see results from optimization? <a class="header-anchor" href="#how-long-does-it-take-to-see-results-from-optimization" aria-label="Permalink to &quot;How long does it take to see results from optimization?&quot;">​</a></h3><p>There is no fixed timeline, because platforms don&#39;t publish how quickly they re-index metadata or how heavily they weight popularity signals. What you can expect:</p><p><strong>Soon after a change</strong>:</p><ul><li>Your updated title or description appears on the platforms once your host&#39;s feed refreshes and each platform re-fetches it (usually hours to a few days)</li><li>New keywords begin tracking in PodSEO with the next ranking collection</li></ul><p><strong>Over the following weeks</strong>:</p><ul><li>Metadata-driven position changes for the keywords you targeted often show up within a few weeks; watch them in <a href="/features/keyword-tracker.html">Keyword Tracker</a></li><li>Popularity-driven movement (followers, plays, completions) builds more slowly and depends on how many new listeners your episodes attract</li></ul><p>Rather than waiting for a promised milestone, compare each keyword against its own starting position, give a change at least a few weeks and a new episode or two before judging it, and keep applying recommendations consistently. The <a href="/academy/podcast-analytics-decoded-which-metrics-actually-matter-for-seo.html">analytics guide</a> explains a review routine.</p><br><h3 id="what-happens-after-i-add-a-podcast" tabindex="-1">What happens after I add a podcast? <a class="header-anchor" href="#what-happens-after-i-add-a-podcast" aria-label="Permalink to &quot;What happens after I add a podcast?&quot;">​</a></h3><p>When you add a podcast, PodSEO sets up your baseline across Apple Podcasts, Spotify, Amazon Music, and YouTube Music — capturing your current rankings, the keywords you already appear for, and similar podcasts in your category. This gives you a starting point to measure your optimization efforts against.</p><p>Your dashboard will populate as this information becomes available, and you&#39;ll be notified when everything is ready to explore.</p><br><h3 id="can-i-track-keywords-i-m-not-currently-ranking-for" tabindex="-1">Can I track keywords I&#39;m not currently ranking for? <a class="header-anchor" href="#can-i-track-keywords-i-m-not-currently-ranking-for" aria-label="Permalink to &quot;Can I track keywords I&#39;m not currently ranking for?&quot;">​</a></h3><p>Yes! Use <strong>Monitored Keywords</strong> to monitor any keyword, whether you&#39;re currently ranking or not. This is perfect for:</p><ul><li><strong>Competitor Analysis</strong>: Track keywords your competitors rank for</li><li><strong>Market Research</strong>: Monitor emerging trends in your niche</li><li><strong>Future Strategy</strong>: Watch keywords you plan to target later</li><li><strong>Performance Goals</strong>: Track progress toward ranking for new terms</li></ul><p>Monitored keywords don&#39;t count toward the three-Primary cap, but they do count toward your plan&#39;s total keyword allowance, and they provide valuable competitive intelligence. Learn more in our <a href="/features/keyword-strategy.html">Keyword Strategy guide</a> or explore <a href="/features/competitor-finder.html">competitor discovery tools</a> to find new keywords to track.</p><h3 id="can-podseo-show-how-my-podcast-performs-on-youtube" tabindex="-1">Can PodSEO show how my podcast performs on YouTube? <a class="header-anchor" href="#can-podseo-show-how-my-podcast-performs-on-youtube" aria-label="Permalink to &quot;Can PodSEO show how my podcast performs on YouTube?&quot;">​</a></h3><p>Yes. Connect your podcast&#39;s YouTube channel and activate <a href="/features/youtube-insights.html">YouTube Insights</a> (sidebar → <strong>YouTube</strong>). You&#39;ll see your channel&#39;s views, watch hours, subscriber change, where your views come from, and the real searches that bring viewers to your videos, compared with the keywords you track in PodSEO. PodSEO also matches your videos to your podcast episodes and suggests tracked keywords to add to your video titles.</p><p>The connection is read-only: PodSEO never edits your videos. It&#39;s the same connection used to publish Shorts from <a href="/features/social-publishing.html">Social Publishing</a>. YouTube Insights is available on every plan; the free plan covers channel performance, one search term, and your latest episode, while paid plans unlock every search term and your recent episodes.</p><p><strong>YouTube vs YouTube Music</strong>: YouTube Music is the podcast directory inside the YouTube Music app, and PodSEO tracks your podcast rankings there like on Apple and Spotify. YouTube Insights is about your <strong>YouTube channel</strong> and its videos.</p><br><hr><h2 id="need-more-help" tabindex="-1">Need More Help? <a class="header-anchor" href="#need-more-help" aria-label="Permalink to &quot;Need More Help?&quot;">​</a></h2><ul><li><strong>Getting Started</strong>: Follow our <a href="/getting-started/first-steps.html">step-by-step first steps guide</a> or <a href="/getting-started/workflow.html">PodSEO Workflow</a></li><li><strong>Something not working?</strong>: See <a href="/more/troubleshooting.html">Troubleshooting</a></li><li><strong>Feature Documentation</strong>: Browse our complete feature guides for detailed instructions</li><li><strong>AI Assistant</strong>: Chat with <a href="/features/lucia-ai-assistant.html">LUCIA</a> for personalized help and answers</li><li><strong>Contact Support</strong>: Reach out via <a href="https://podseo.com/settings/contact" target="_blank" rel="noreferrer">Settings → Contact Us</a> for additional assistance</li></ul><p>For account questions, see <a href="/features/billing-and-account.html">Billing and Account Settings</a> and <a href="/features/teams-and-organizations.html">Teams and Organizations</a>. Client reporting and approvals are covered in <a href="/features/agency-workspace.html">Agency Workspace</a>.</p>',67)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
